"""Generate inert action shells and native basic impact; preserve Gojo body/stats/growth."""
from pathlib import Path
import copy,json
ROOT=Path(__file__).resolve().parents[1];P=ROOT/'mods/tfm2_jjk';ID='tfm2_custom_gojo'
def generate():
    path=P/'champion'/f'{ID}.data_champion';d=json.loads(path.read_text());d['passive']={'passive_ref':'tfm2_custom_ai:gojo','params':{}}
    d['attack']['effect']={'type':'Native','effect_ref':'tfm2_custom_ai:gojo_basic'}
    for k in ['skill','skill2','ult']:
        d[k].update(duration=6,cooltime=5184000,start_timing=3,range=1,casting_type='Targeting',casting_target='EnemyChampionInCC',effect={'type':'Combine','effects':[]})
    d['view_effects']=[v for v in d.get('view_effects',[]) if not v['name'].startswith('tfm2_custom_gojo_new_')]+[{'type':'Animation','name':f'tfm2_custom_gojo_new_{i}','anim':'asset/tfm2_jjk/vfx/gojo_rework','tag':f'fx{i}','z':1,'is_follow':False} for i in range(12)]
    d['view_effects']=[v for v in d['view_effects'] if not v['name'].startswith('tfm2_custom_gojo_ring_')]+[{'type':'Animation','name':f'tfm2_custom_gojo_ring_{tag}','anim':'asset/tfm2_jjk/vfx/gojo_rework','tag':tag,'z':-1,'is_follow':False} for tag in [f'domain{n}' for n in range(8)]+[f'warning{n}' for n in [3,20,26,32,36,76]]]
    d['view_effects']=[v for v in d['view_effects'] if not v['name'].startswith('tfm2_custom_gojo_flight_')]+[{'type':'Animation','name':f'tfm2_custom_gojo_flight_{tag}{n}','anim':'asset/tfm2_jjk/vfx/gojo_rework','tag':f'flight_{tag}{n}','z':1,'is_follow':False} for tag,count in [('blue',4),('red',4),('purple',6)] for n in range(count)]
    d['view_buffs']=[v for v in d.get('view_buffs',[]) if not v['name'].startswith('gj_')]
    for key in ['ce','strain']:
        for i in range(21):d['view_buffs'].append({'type':'Animated','name':f'gj_{key}{i}','anim':'asset/tfm2_jjk/vfx/gojo_rework','tag':key+str(i),'z':3})
    for name,tag in [('gj_six_eyes','six_eyes'),('gj_amp','amplified'),('gj_burnout','burnout'),('gj_inf_paused','infinity_paused'),('gj_inf_broken','infinity_break')]:d['view_buffs'].append({'type':'Animated','name':name,'anim':'asset/tfm2_jjk/vfx/gojo_rework','tag':tag,'z':1})
    path.write_text(json.dumps(d,indent=2)+'\n');(ROOT/'editor/gojo-champion.json').write_text(json.dumps(d,separators=(',',':'))+'\n')
    text={'name':'Gojo','skill':'Six Eyes: 100 CE, efficient techniques and separate strain. CE regenerates 3/s (6/s after four seconds without champion damage). Infinity: 200 + 50% AP, 75% skill / 30% basic damage reduction, 1 CE/s upkeep; broken shield reforms after 15s for 5 CE. During CE shortage or burnout the remaining shield can absorb damage, but reductions and rebuilding pause; allied shields stay untouched. Blue: 6 CE / 5 strain, 10s cooldown, 0.4s preparation. Existing Blue damage/pull; grants two enhanced punches for 4s (+15 + 20% AP each). Maximum Output: 12 CE / 15 strain, 0.9s preparation, 135% damage and 36000 radius.','skill2':'Red: 10 CE / 7 strain, 9s cooldown, 0.4s preparation; existing direct hit/explosion. Maximum Output: 20 CE / 18 strain, 1s preparation, 135% damage and 26000 radius. Native contextual techniques: RCT heals 80 + 50% AP over 1s (20 CE, 8 strain, 14s cooldown); Spatial Step travels up to 32000 (8 CE, 8 strain, 12s cooldown). After Blue/Red hits a champion, two melee hits on that champion within 4s earn Black Flash (+30 + 35% AP; 6s trigger cooldown). Each qualifying punch costs 1 CE / 1 strain. Black Flash removes 10 strain and grants 20% more Gojo-kit damage for 8s; subsequent flashes refresh without stacking.','ult':'Unlimited Void: 40 CE / 45 strain, 60s cooldown, 76000 radius. One nearest allied champion is chosen once as the protected guest; every other ally caught is stunned and sealed alongside enemies. Gojo is free after the casting lock. Existing slow/fast expansion retained. Domain closure causes 3s burnout. At 100 strain: 4s burnout, Domain collapses; Infinity reductions and Limitless techniques pause, melee/RCT remain. Purple requires ultimate learned and both Blue/Red ready: 34 CE / 30 strain, 20s cooldown, 200 + 160% AP; shares Blue/Red cooldowns. No mastery variants.'}
    loc=json.loads((P/'text/champion.i18n').read_text());loc.setdefault('en',{}).setdefault('description',{})[ID]=text;(P/'text/champion.i18n').write_text(json.dumps(loc,indent=2)+'\n')
    (ROOT/'editor/gojo-preset.js').write_text('window.GOJO_PRESET='+json.dumps({'json':d,'text':text,'vfx':'gojo','sprite':'gojo'},separators=(',',':'))+';\n')
if __name__=='__main__':generate()
